import { execSync } from 'child_process';

const RENDER_KEY = 'rnd_1H0XCquMZQTRyAnHgbEv8dVWYPVs';
const API_SVC = 'srv-d7t9ivreo5us73ftose0';
const WORKER_SVC = 'srv-d9i15fg4n6ts73bn00j0';

function fetchAllEnvVars(svcId, label) {
  console.log(`\n=== ALL env vars on ${label} (${svcId}) ===`);
  try {
    const cmd = `curl -sS -m 15 -H "Authorization: Bearer ${RENDER_KEY}" "https://api.render.com/v1/services/${svcId}/env-vars"`;
    const out = execSync(cmd, { encoding: 'utf-8' });
    const vars = JSON.parse(out);
    if (!Array.isArray(vars)) {
      console.log('Response:', out.substring(0, 300));
      return;
    }
    for (const v of vars) {
      const name = v.key || v.name || '?';
      const val = v.value || '';
      // Mask secrets but show length and first/last 2 chars
      const isSecret = /SECRET|KEY|TOKEN|PASSWORD|PAT/i.test(name);
      if (isSecret) {
        console.log(`  ${name}: len=${val.length} [${val.substring(0,2)}...${val.slice(-2)}]`);
      } else {
        console.log(`  ${name}: ${val.substring(0, 60)}`);
      }
    }
    console.log(`Total: ${vars.length} env vars`);
  } catch (e) {
    console.log('Error:', e.message.substring(0, 300));
  }
}

fetchAllEnvVars(API_SVC, 'API (ivx-holdings-platform)');
fetchAllEnvVars(WORKER_SVC, 'Worker (ivx-senior-dev-01)');
SCRIPT
node /tmp/ivx-full-cred-audit.mjs 2>&1

