cat > /tmp/ivx-aws-sdk-test.mjs << 'SCRIPT'
import { execSync } from 'child_process';

const RENDER_KEY = 'rnd_1H0XCquMZQTRyAnHgbEv8dVWYPVs';
const API_SVC = 'srv-d7t9ivreo5us73ftose0';

function fetchEnvVar(name) {
  const cmd = `curl -sS -m 10 -H "Authorization: Bearer ${RENDER_KEY}" "https://api.render.com/v1/services/${API_SVC}/env-vars/${name}"`;
  const out = execSync(cmd, { encoding: 'utf-8' });
  const d = JSON.parse(out);
  const ev = d.envVar || d;
  return (ev.value || '').trim();
}

const accessKey = fetchEnvVar('AWS_ACCESS_KEY_ID');
const secretKey = fetchEnvVar('AWS_SECRET_ACCESS_KEY');
const region = fetchEnvVar('AWS_REGION') || 'us-east-1';

console.log('Access Key:', accessKey);
console.log('Secret Key len:', secretKey.length, 'first4:', secretKey.substring(0,4), 'last4:', secretKey.slice(-4));
console.log('Region:', region);

// Use the OFFICIAL AWS SDK - if this also fails, it's definitively the wrong secret
const { S3Client, GetBucketLocationCommand, ListObjectsV2Command, PutObjectCommand } = await import('/home/user/rork-app/expo/node_modules/@aws-sdk/client-s3/dist-cjs/index.js');

const client = new S3Client({
  region,
  credentials: {
    accessKeyId: accessKey,
    secretAccessKey: secretKey,
  },
});

console.log('\n=== Test 1: GetBucketLocation (official SDK) ===');
try {
  const result = await client.send(new GetBucketLocationCommand({ Bucket: 'ivxholding.com' }));
  console.log('SUCCESS! Bucket region:', result.LocationConstraint || 'us-east-1 (default)');
} catch (e) {
  console.log('FAILED:', e.name, e.message?.substring(0, 300));
  console.log('Error code:', e.Code || e.$metadata?.httpStatusCode);
}

console.log('\n=== Test 2: ListObjectsV2 (official SDK) ===');
try {
  const result = await client.send(new ListObjectsV2Command({ Bucket: 'ivxholding.com', Prefix: 'apk/', MaxKeys: 5 }));
  console.log('SUCCESS! Contents:');
  if (result.Contents) {
    for (const obj of result.Contents) {
      console.log(`  ${obj.Key} - ${obj.Size} bytes - ${obj.LastModified?.toISOString()}`);
    }
  } else {
    console.log('  (no objects found)');
  }
} catch (e) {
  console.log('FAILED:', e.name, e.message?.substring(0, 300));
}
SCRIPT
node /tmp/ivx-aws-sdk-test.mjs 2>&1

